-- CREATE TABLE customer_segments AS SELECT CustomerID, RFM_Score, CASE WHEN RFM_Score IN ('555','554','545','455','544','454','445') THEN 'Champions' WHEN RFM_Score LIKE '5%' THEN 'Loyal Customers' WHEN RFM_Score LIKE '4%' THEN 'Potential Loyalists' WHEN RFM_Score LIKE '2%' OR RFM_Score LIKE '3%' THEN 'At Risk' ELSE 'Needs Attention' END AS Segment FROM (SELECT CustomerID, CONCAT(R_Score, F_Score, M_Score) AS RFM_Score FROM rfm_scores) AS scored;
SELECT COUNT(*) AS TotalCustomers FROM customer_segments;
SELECT Segment, COUNT(*) AS CustomerCount FROM customer_segments GROUP BY Segment ORDER BY CustomerCount DESC;